          this.selectedWorkShift = this.membersItem.presence_settings.work_shift_timings_name;
          await this.fetch_details();
          this.locationupdate = "scananywhere";
          try {
            if (this.membersItem?.presence_settings && typeof this.membersItem.presence_settings === "string") {
              const scandetails = JSON.parse(this.membersItem.presence_settings);
              if (scandetails.location_id === "" && scandetails.is_scan_anywhere === true) {
                this.locationupdate = "scananywhere";
                this.loaction = "";
              } else if (scandetails.location_id === "ANY_LOCATION" && scandetails.is_scan_anywhere === false) {
                this.locationupdate = "geoloc";
                this.loaction = "";
              } else {
                this.locationupdate = "assignloc";
                this.loaction = scandetails.location_id;
              }
            } else if (this.membersItem?.presence_settings) {
              // If presence_settings is already an object
              const scandetails = this.membersItem.presence_settings;
              if (scandetails.location_id === "" && scandetails.is_scan_anywhere === true) {
                this.locationupdate = "scananywhere";
                this.loaction = "";
              } else if (scandetails.location_id === "ANY_LOCATION" && scandetails.is_scan_anywhere === false) {
                this.locationupdate = "geoloc";
                this.loaction = "";
              } else {
                this.locationupdate = "assignloc";
                this.loaction = scandetails.location_id;
              }
            } else {
              // Default values if no settings exist
              this.locationupdate = "scananywhere";
              this.loaction = "";
            }
          } catch (error) {
            console.error("Error parsing presence settings:", error);
            // Set default values in case of error
            this.locationupdate = "scananywhere";
            this.loaction = "";
            this.$emit("errorMsg", "Error loading presence settings. Using default values.");
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async validate_inputs() {
      const {
        valid
      } = await this.$refs.form?.validate?.();
      if (valid) {
        this.update_mutation();
      }
    },
    locationCheck() {
      this.loaction = "";
    },
    fetch_details() {
      this.loactionitems = [];
      this.locationList.forEach(element => {
        this.loactionitems.push({
          title: element.location_name,
          location_id: element.location_id
        });
      });
    },
    async update_mutation() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_user_presence_settings, {
          input: {
            user_id: this.membersItem.user_id,
            presence_settings: JSON.stringify({
              work_shift_timings_id: this.selectedWorkShift?.work_shift_timings_id || null,
              work_shift_timings_name: this.selectedWorkShift?.work_shift_timings_name || null,
              is_scan_anywhere: this.locationupdate == "scananywhere" ? true : false,
              location_id: this.locationupdate == "scananywhere" ? "" : this.locationupdate == "geoloc" ? "ANY_LOCATION" : this.loaction
            })
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.update_user_presence_settings);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
